import socket, concurrent.futures
def chk(a):
    host, port = a
    s=socket.socket(); s.settimeout(0.4)
    try:
        s.connect((host,port)); return (host,port)
    except: return None
    finally: s.close()
targets=[(f"172.21.0.{i}",p) for i in range(1,40) for p in (80,8080,8000,5000,443)]
with concurrent.futures.ThreadPoolExecutor(100) as ex:
    for r in ex.map(chk,targets):
        if r: print("OPEN",r)
print("scan done")
EOF"}

